# owner: platform
"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def snap(minute: int, step: int) -> int:
    """Nearest step, with exact halves going up."""
    return (minute + step // 2) // step * step


def span_label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes:02d}m)"


def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    return [
        span_label(Span(snap(s.start, step), snap(s.end, step)))
        for s in spans
    ]
