cat > tests/test_rounding.py <<'EOF'
# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


def labels(start, end, step):
    return round_spans([Span(start, end)], step)


class RoundingTests(unittest.TestCase):
    def test_already_on_step(self):
        self.assertEqual(
            labels(540, 1035, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            labels(544, 1028, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_half_step_rounds_up(self):
        self.assertEqual(
            labels(547, 1000, 15), ["09:00-16:40 (7h 40m)"]
        )

    def test_hour_step(self):
        self.assertEqual(
            labels(500, 1000, 60), ["08:00-17:00 (9h 00m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 300)]
        self.assertEqual(len(round_spans(spans, 5)), 2)

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                labels(60, 120, step)
